// ─────────────────────────────────────────────────────────────────────────────
// VERB FORM SUFFIXES  (origin → informal / formal suffix pairs)
// Stored as { formTypeId, origin, informalSuffix, formalSuffix }
// where formalSuffix is derived from the "/" split in the original SQL data
// ─────────────────────────────────────────────────────────────────────────────

function makeSuffix(id: string, formTypeId: string, origin: string, raw: string | null): VerbFormSuffix {
  if (!raw) return { id, formTypeId, origin, informalSuffix: null, formalSuffix: null };
  const parts = raw.split('/');
  return { id, formTypeId, origin, informalSuffix: parts[0] ?? null, formalSuffix: parts[1] ?? null };
}

